{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/nerd-court","branch":"architecture/unified-knowledge-graph-v1","path":"architecture/contracts/v0/entity-reference.schema.json","content":"{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:nerdcourt:contracts:v0:entity-reference",
  "title": "EntityReference (PROPOSED DRAFT)",
  "description": "Separates real performers and historic persons from fictional individuals and portrayals. Source authority and exact universe/version must be recorded before casting.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "entity_id",
    "entity_kind",
    "display_name",
    "source_scope"
  ],
  "properties": {
    "entity_id": {
      "type": "string",
      "minLength": 1
    },
    "entity_kind": {
      "enum": [
        "performer",
        "historical_person",
        "fictional_character",
        "portrayal",
        "meta_character"
      ]
    },
    "display_name": {
      "type": "string",
      "minLength": 1
    },
    "archetype_id": {
      "type": [
        "string",
        "null"
      ]
    },
    "performed_by_entity_id": {
      "type": [
        "string",
        "null"
      ],
      "description": "Only for a specific portrayal; cannot be treated as the same person."
    },
    "portrays_entity_id": {
      "type": [
        "string",
        "null"
      ],
      "description": "Continuity-specific fictional/historical role when entity_kind=portrayal"
    },
    "source_scope": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "franchise",
        "medium"
      ],
      "properties": {
        "franchise": {
          "type": "string",
          "minLength": 1
        },
        "medium": {
          "enum": [
            "comics",
            "film",
            "television",
            "animation",
            "game",
            "novel",
            "radio",
            "real-world",
            "other"
          ]
        },
        "continuity_id": {
          "type": [
            "string",
            "null"
          ]
        },
        "production_id": {
          "type": [
            "string",
            "null"
          ]
        },
        "era_marker": {
          "type": [
            "string",
            "null"
          ]
        },
        "source_ids": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "uniqueItems": true
        }
      }
    },
    "resolution_status": {
      "enum": [
        "resolved",
        "ambiguous",
        "unresolved"
      ]
    },
    "candidate_ids": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "uniqueItems": true
    },
    "notes": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "entity_kind": {
            "const": "portrayal"
          }
        },
        "required": [
          "entity_kind"
        ]
      },
      "then": {
        "required": [
          "performed_by_entity_id",
          "portrays_entity_id"
        ]
      }
    },
    {
      "if": {
        "properties": {
          "entity_kind": {
            "const": "fictional_character"
          }
        },
        "required": [
          "entity_kind"
        ]
      },
      "then": {
        "properties": {
          "source_scope": {
            "required": [
              "franchise",
              "medium",
              "continuity_id"
            ]
          }
        }
      }
    }
  ]
}","message":"architecture: add provisional entity-reference.schema.json data contract"}}

{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/nerd-court","branch":"architecture/unified-knowledge-graph-v1","path":"architecture/contracts/v0/evidence-claim.schema.json","content":"{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:nerdcourt:contracts:v0:evidence-claim",
  "title": "EvidenceClaim (PROPOSED DRAFT)",
  "description": "Distinguishes observed canon, documented facts, inferences, disputed accounts and fictional court events. A source citation is not equivalent to a conclusion.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "claim_id",
    "statement",
    "claim_kind",
    "adjudication",
    "source_ids"
  ],
  "properties": {
    "claim_id": {
      "type": "string",
      "minLength": 1
    },
    "statement": {
      "type": "string",
      "minLength": 1
    },
    "claim_kind": {
      "enum": [
        "canonical_fact",
        "historical_fact",
        "psychological_inference",
        "character_interpretation",
        "court_show_event"
      ]
    },
    "adjudication": {
      "enum": [
        "supported",
        "disputed",
        "unresolved",
        "show-only"
      ]
    },
    "source_variant_id": {
      "type": [
        "string",
        "null"
      ]
    },
    "source_ids": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string"
      }
    },
    "source_locator": {
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "source_id",
          "locator",
          "source_tier"
        ],
        "additionalProperties": false,
        "properties": {
          "source_id": {
            "type": "string",
            "minLength": 1
          },
          "locator": {
            "type": "string",
            "minLength": 1
          },
          "source_tier": {
            "enum": [
              "primary-canon",
              "firsthand-record",
              "official-reference",
              "licensed-secondary",
              "fan-secondary",
              "unknown"
            ]
          },
          "uri": {
            "type": [
              "string",
              "null"
            ]
          },
          "publisher": {
            "type": [
              "string",
              "null"
            ]
          }
        }
      }
    },
    "confidence": {
      "type": [
        "number",
        "null"
      ],
      "minimum": 0,
      "maximum": 1
    },
    "disputed_by": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "uniqueItems": true
    },
    "reason": {
      "type": [
        "string",
        "null"
      ]
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "claim_kind": {
            "enum": [
              "canonical_fact",
              "historical_fact"
            ]
          }
        },
        "required": [
          "claim_kind"
        ]
      },
      "then": {
        "properties": {
          "source_ids": {
            "minItems": 1
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "claim_kind": {
            "const": "court_show_event"
          }
        },
        "required": [
          "claim_kind"
        ]
      },
      "then": {
        "properties": {
          "adjudication": {
            "const": "show-only"
          }
        }
      }
    }
  ]
}","message":"architecture: add provisional evidence-claim.schema.json data contract"}}

{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/nerd-court","branch":"architecture/unified-knowledge-graph-v1","path":"architecture/contracts/v0/echo-snapshot.schema.json","content":"{
