    "allowed_reuse_episode_ids": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string"
      }
    },
    "source_claim_ids": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "uniqueItems": true
    },
    "scene_events": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  }
}","message":"architecture: add provisional echo-snapshot.schema.json data contract"}}

